<div class="page-heading admin-review-heading"><a href="/admin">← Administration</a><h1><?=e($r['title'])?></h1><p><?=status_badge($r['status'])?> <span class="status"><?=e($r['moderation'])?></span></p><div class="actions primary-actions"><?php if(in_array($r['status'],['Blocked','Needs Clarification'],true)): ?><a class="button" href="#workflow-response">Respond to blocker</a><?php endif ?><a class="button" href="#request-decision">Moderate request</a><a class="button secondary" href="#items">Review contributions</a><a class="button secondary" href="#ledger">Manage findings</a></div><p class="fine">Immutable ID: <?=e($rid)?> · Context v<?=e($r['context_version'])?> · Created <?=e($r['created_at'])?></p></div>
