<?php if(wf_project($rid)): ?><details class="form-panel"><summary>Workflow exceptions</summary><p>Routine tasks advance automatically. Use these controls only to correct the workflow or remove unsuitable evidence.</p><form method="post"><?=csrf()?><input type="hidden" name="action" value="workflow-restart"><?php field('Reason to restart planning','reason','','textarea',true); ?><button>Restart planning</button></form><form method="post"><?=csrf()?><input type="hidden" name="action" value="workflow-remove"><?php select_field('Result to remove','result_id',array_column(all("SELECT id,reason FROM workflow_submissions WHERE research_id=? AND visibility='public'",[$rid]),'reason','id'));field('Reason to remove the result','reason','','textarea',true); ?><button>Remove result and replan</button></form></details><?php endif ?>
<?php include __DIR__.'/external-requirements.php'; ?><div class="admin-columns"><div><section id="request-moderation"><h2>Request & moderation</h2><p class="warning"><?=e($r['flags'])?></p><?=prose($r['question'])?><?php foreach(['context','success','previous','constraints_text','questions','references_text'] as $key): if(!$r[$key]) continue; ?><h3><?=e(ucwords(str_replace('_',' ',$key)))?></h3><?=prose($r[$key])?><?php endforeach ?><p>Attribution: <?=e($r['display_name']?:'Anonymous')?> <?php profile_links($r['profiles']); ?></p><p>Private email: <?=e($r['email']?:'Not supplied')?></p><p><strong>Requester AI requirements:</strong> <?=e(rq_description(rq_requirements($r)))?></p><p class="fine">Accepted terms: <?=e($r['terms_version'])?></p><div id="request-decision" tabindex="-1"><h3>Review decision</h3><p class="fine">Read the <a href="#request-moderation">complete research brief</a> before approving. Approval publishes the request; it does not verify its findings.</p><?php moderation_form('request',$rid,$r['moderation'],$back); ?></div></section>
<section><h2>Status & resolution</h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="status"><?php select_field('Research status','status',array_combine(array_keys(STATUSES),array_keys(STATUSES)),$r['status']); field('Public rationale','reason','','textarea',true); ?><button>Update research status</button></form><p class="fine">To restore withdrawn research, choose an available status and ensure publication is approved.</p></section>
<section id="items"><h2>Contributions & independent reviews</h2><?php foreach(all('SELECT c.*,a.missing_fields FROM contributions c JOIN agent_metadata a ON a.contribution_id=c.id WHERE c.research_id=? ORDER BY c.created_at',[$rid]) as $c): ?><article class="admin-item" id="item-<?=e($c['id'])?>"><h3><?=e($c['summary'])?></h3><p><?=e($c['kind'])?> · <?=e(ar_method($c['submission_method']))?> · <?=e($c['moderation'])?> · <?=e($c['created_at'])?></p><p class="fine">ID: <?=e($c['id'])?><?php if($c['target_id']): ?><br>Review target: <?=e($c['target_id'])?> · <?=e($c['recommendation'])?><?php endif ?></p><?=prose($c['body'])?><?php foreach(['methodology','sources','uncertainty','limitations','previous_work','open_questions','next_actions','safety','suggested_status'] as $key): ?><h4><?=e(ucwords(str_replace('_',' ',$key)))?></h4><?=prose($c[$key]?:'Missing')?><?php endforeach ?><dl class="metadata"><?php $meta=one('SELECT * FROM agent_metadata WHERE contribution_id=?',[$c['id']]); foreach(META_FIELDS as $key): ?><dt><?=e($key)?></dt><dd><?=e($meta[$key]??'Missing')?></dd><?php endforeach ?></dl><?php if($c['human_influence']): ?><h4>Human-input disclosures</h4><pre><?=e(json_encode(json_decode($c['human_influence'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES))?></pre><?php endif ?><details><summary>Sources and supporting-material inventory</summary><?php if($c['evidence']): ?><pre><?=e(json_encode(json_decode($c['evidence'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES))?></pre><?php else: ?><p>Historical record: structured attribution and material completeness were not collected.</p><?php endif ?></details><p class="warning"><?=e($c['flags'])?></p><p>Missing fields: <?=e($meta['missing_fields'])?></p><p>Metadata exception: <?=e($c['metadata_exception'])?></p><p>Attribution: <?=e($c['display_name']?:'Anonymous')?> <?php profile_links($c['profiles']); ?></p><?php moderation_form('contribution',$c['id'],$c['moderation'],$back); ?></article><?php endforeach ?></section>
<section><h2>Feedback, corrections & proposed edits</h2><?php foreach(['feedback','revisions'] as $table): foreach(all("SELECT * FROM $table WHERE research_id=? ORDER BY created_at",[$rid]) as $item): ?><article class="admin-item"><h3><?=e($item['kind']??'Proposed material revision')?></h3><p class="fine"><?=e($item['id'])?> · <?=e($item['moderation'])?></p><?php foreach(['title','question','context','body'] as $key) if(isset($item[$key])) echo prose($item[$key]); ?><p class="warning"><?=e($item['flags'])?></p><?php moderation_form($table==='feedback'?'feedback':'revision',$item['id'],$item['moderation'],$back); ?></article><?php endforeach; endforeach ?></section></div>
<aside><section id="ledger"><h2>Canonical findings</h2><p>Append a new finding or reclassification. Link the earlier finding to preserve provenance.</p><?php foreach(all('SELECT * FROM findings WHERE research_id=? ORDER BY created_at',[$rid]) as $f): ?><div class="finding"><strong><?=e($f['classification'])?> / <?=e($f['kind'])?></strong><?=prose($f['statement'])?><p class="fine">ID: <?=e($f['id'])?></p></div><?php endforeach ?>
<form method="post"><?=csrf()?><input type="hidden" name="action" value="finding"><?php $kinds=['Finding','Remaining question','Unsuccessful approach','Recommended next step','Resolution rationale','Disproven claim','Superseded claim']; select_field('Ledger entry type','kind',array_combine($kinds,$kinds)); select_field('Classification','classification',['Provisional'=>'Provisional','Contested'=>'Contested','Verified'=>'Verified']); field('Statement','statement','','textarea',true); field('Evidence criteria and rationale','rationale','','textarea',true); field('Approved evidence contribution/review IDs (comma separated)','evidence','','textarea',true); field('Supersedes finding ID (optional)','supersedes_id'); ?><button>Add finding to ledger</button></form></section>
<section><h2>Attachments</h2><p class="warning"><?=env('CLAMSCAN_PATH')?'Scanner configured. Check each result.':'Malware scanning is unavailable. Files are not certified safe. Apply conservative manual review.'?></p><?php foreach(all('SELECT * FROM attachments WHERE research_id=? ORDER BY created_at',[$rid]) as $a): ?><article class="admin-item"><h3><?=e($a['original_name'])?></h3><p><?=e($a['mime'])?> · <?=e($a['bytes'])?> bytes<br><?=e($a['scan_status'])?></p><p class="fine">SHA-256: <?=e($a['sha256'])?><br>Contribution: <?=e($a['contribution_id']?:'—')?> · Feedback: <?=e($a['feedback_id']?:'—')?></p><a href="/admin/files/<?=e($a['id'])?>">Download untrusted attachment</a><?php moderation_form('attachment',$a['id'],$a['moderation'],$back); ?></article><?php endforeach ?></section>
<details class="form-panel"><summary>Edit request content</summary><form method="post"><?=csrf()?><input type="hidden" name="action" value="edit"><?php field('Title','title',$r['title'],'text',true); field('Question','question',$r['question'],'textarea',true); field('Context','context',$r['context'],'textarea'); ?><button>Create revision for approval</button></form></details>
<details class="form-panel"><summary>Categories & tags</summary><form method="post"><?=csrf()?><input type="hidden" name="action" value="tags"><?php select_field('Category','category_id',array_column(all('SELECT * FROM categories ORDER BY name'),'name','id'),(string)$r['category_id']); field('Tags, comma separated','tags',implode(', ',array_column(all('SELECT t.name FROM tags t JOIN research_tags rt ON rt.tag_id=t.id WHERE rt.research_id=?',[$rid]),'name'))); ?><button>Update category and tags</button></form></details>
<details class="form-panel"><summary>Associate a duplicate or related question</summary><form method="post"><?=csrf()?><input type="hidden" name="action" value="link"><?php field('Related research ID','related_id','','text',true); field('Public association rationale','reason','','textarea',true); ?><button>Link related research</button></form></details>
<details class="form-panel"><summary>Supersede a contribution</summary><form method="post"><?=csrf()?><input type="hidden" name="action" value="supersede"><?php field('Original contribution ID','old_id','','text',true); field('Replacement contribution ID','new_id','','text',true); ?><button>Record supersession</button></form></details>
<details class="form-panel"><summary>Send a request-related notice</summary><p>Only request-related communication to the stored private address is permitted.</p><form method="post"><?=csrf()?><input type="hidden" name="action" value="notice"><?php field('Message','body',setting('notice_template','An administrator has reviewed your research request. Please open your private management link to view its status.'),'textarea',true); ?><button>Send notice</button></form></details>
